return [
  { json: { url: 'https://weworkremotely.com/categories/remote-full-stack-programming-jobs.rss' } },
  { json: { url: 'https://weworkremotely.com/categories/remote-front-end-programming-jobs.rss' } },
  { json: { url: 'https://weworkremotely.com/categories/remote-back-end-programming-jobs.rss' } },
];

// ===== COMO O FILTRO DECIDE =====
// Antes de tudo: vaga velha demais (idade_maxima_dias) ou já enviada antes (mesmo id, ou mesma empresa+título) é ignorada.
// Vagas de e-mail chegam prontas (os parsers de cada site extraem antes do filtro); as das APIs são normalizadas aqui.
// Depois, a função score() aplica as regras abaixo, NESTA ordem (a primeira que barrar descarta a vaga):
//  1. Senioridade excluída no título ..... (senioridade_excluida: estágio, sênior, lead...) descarta. Nem "Júnior" nem palavra
//                                          prioritária salvam; para voltar a receber estágio, tire as palavras desse campo.
//  2. Outra profissão no título .......... (palavras_bloqueadas_no_titulo: devops, qa, sales...) descarta,
//                                          a não ser que o título tenha uma palavra de palavras_que_liberam_vaga.
//                                          Ex.: para começar a aplicar para QA, ponha "qa" em palavras_que_liberam_vaga.
//  3. Stack indesejada no título ......... (palavras_bloqueadas_stack: java, php...) descarta, a não ser que:
//                                          - tenha palavra que libera a vaga: passa normal; ou
//                                          - tenha "Júnior"/"Jr": passa "COM RESSALVAS" (aviso ⚠️ no Discord e na página).
//  4. Vaga de API sem palavra de cargo ... (palavras_do_cargo) descarta. Vaga de e-mail e palavra que libera a vaga já contam como cargo.
//  5. Local .............................. se a vaga traz local e ele não está em locais_aceitos, descarta
//                                          (exceto quando o parser do site marca localConfiavel).
//  6. Nota de 0 a 10 ..................... pesos nas constantes PESO_* e PENAL_* logo abaixo; os limites de anos de experiência
//                                          (nota_cai_muito_a_partir_de_x_anos, nota_cai_a_partir_de_x_anos, nota_sobe_ate_x_anos) vêm das Configurações. Abaixo de nota_minima: descarta.
// Vaga "com ressalvas" aparece depois das normais, com o motivo, para você decidir ao clicar.
// A nota é heurística (palavras e limites do nó "Configurações", pesos nas constantes abaixo), não IA.

// ===== CONFIGURAÇÕES =====
// Três camadas de ajuste:
//  - PERFIL (muda com você): palavras, nota mínima, tecnologias, anos de experiência -> nó "Configurações", sem mexer aqui.
//  - REGRA DE NEGÓCIO (como a nota é calculada, limites do sistema) -> as constantes logo abaixo. Só muda se a fórmula mudar.
//  - AMBIENTE (muda com a máquina): fuso e URL do Discord -> arquivo .env.
const FUSO = $env.GENERIC_TIMEZONE || 'America/Sao_Paulo'; // fuso das datas e horas: vem do .env (GENERIC_TIMEZONE); sem ele, Brasília
const MAX_CHARS = 3500;           // tamanho máximo de cada mensagem (a descrição de um embed aceita até 4096)
const SEEN_TTL_DAYS = 60;         // por quanto tempo lembrar de vagas já enviadas
// ⚠️ NÃO MEXA NOS PESOS ABAIXO SEM ENTENDER: um depende do outro e da nota_minima (quadro completo no README).
//   - PESO_CARGO + PESO_JUNIOR precisa ser >= nota_minima (senão vaga de API com palavra que libera a vaga nunca passa).
//   - PESO_EMAIL precisa ser < nota_minima (senão toda vaga de e-mail passa, mesmo sem palavra de cargo).
//   - PENAL_ANOS_MUITO_ALTO precisa ser forte o bastante para derrubar a nota abaixo de nota_minima.
//   - TETO_TECNOLOGIAS: não suba muito nem desça abaixo de 2. BONUS_ANOS_BAIXO: mantenha pequeno.
// Para receber mais ou menos vagas, mude a nota_minima (em Configurações), não os pesos.
// Pesos da nota (regra de negócio):
const PESO_EMAIL = 3;             // vaga que veio de alerta por e-mail (já é uma busca sua)
const PESO_CARGO = 3;             // título tem palavra de cargo (ou palavra que libera a vaga)
const PESO_JUNIOR = 2;            // título tem uma palavra do nível que busco (ou palavra que libera a vaga)
const TETO_TECNOLOGIAS = 5;       // máximo que as tecnologias somam, não importa quantas apareçam
const PENAL_ANOS_MUITO_ALTO = 4;  // desconto quando pede nota_cai_muito_a_partir_de_x_anos ou mais
const PENAL_ANOS_ALTO = 2;        // desconto quando pede nota_cai_a_partir_de_x_anos ou mais
const BONUS_ANOS_BAIXO = 1;       // bônus quando pede até nota_sobe_ate_x_anos
const PENAL_EUA_EUROPA = 3;       // desconto quando o texto restringe a EUA/Canadá/Reino Unido/Europa
// Tema das mensagens (identidade): vem do .env (TEMA). "aranha" (padrão) ou "neutro". Para trocar o texto, edite aqui.
const NEUTRO = $env.TEMA === 'neutro';
const TEXTO_CALMO = (dia, hora, n, aviso) => NEUTRO
  ? `📭 ${dia} ${hora}: nenhuma vaga nova por enquanto (${n} analisadas).${aviso}`
  : `🕸️ ${dia} ${hora}: sentido de aranha calmo, nenhuma vaga nova por enquanto (${n} analisadas).${aviso}`;
const TEXTO_NOVAS = (n, aviso) => NEUTRO
  ? `🔔 Radar de Vagas: ${n} vaga(s) nova(s) pra você! Confira no PC o quanto antes.${aviso}`
  : `🕷️ Meu Sentido de Aranha disparou!! ${n} vaga(s) nova(s) pra você! Confira no PC o quanto antes.${aviso}`;
const LOC_RESTRICT = /(must (be|reside|live)|authorized to work|work authorization|right to work).{0,60}(u\.?s\.?a?\b|united states|canada|\buk\b|europe|\beu\b)/i;

const cfg = $('Configurações').first().json;

// Deixa o texto "comparável": minúsculas, sem acento, hífen e espaços repetidos viram um espaço
const limpa = (s) => String(s ?? '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[-_]/g, ' ').replace(/\s+/g, ' ').trim();
// "a, b, c" vira ['a', 'b', 'c']
const lista = (s) => String(s ?? '').split(',').map(limpa).filter(Boolean);
const escapa = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// detector: .test(texto) diz se o texto tem alguma das palavras, como palavra inteira
// (assim "java" não pega "javascript")
const detector = (termos) => {
  const re = termos.length
    ? new RegExp('(^|[^a-z0-9])(' + termos.map(escapa).join('|') + ')($|[^a-z0-9])')
    : null;
  return {
    test: (texto) => (re ? re.test(limpa(texto)) : false),
    // qual palavra bateu (serve para explicar a ressalva); null se nenhuma
    acha: (texto) => { const m = re ? re.exec(limpa(texto)) : null; return m ? m[2] : null; },
  };
};

// Verificação dos campos numéricos das Configurações: vazio, texto ou fora de faixa distorceria a nota sem ninguém
// perceber (ex.: campo vazio vira 0). Por isso o nó falha de propósito, e o workflow de alerta registra.
const numero = (nome) => {
  const bruto = cfg[nome];
  if (bruto === '' || bruto === null || bruto === undefined || !Number.isFinite(Number(bruto))) {
    throw new Error('Configurações: o campo "' + nome + '" precisa ser um número (está vazio ou inválido)');
  }
  return Number(bruto);
};
const MIN_SCORE = numero('nota_minima');
const MAX_AGE_DAYS = numero('idade_maxima_dias');
const ANOS_MUITO_ALTO = numero('nota_cai_muito_a_partir_de_x_anos');   // anos de experiência pedidos: faixas que mexem na nota
const ANOS_ALTO = numero('nota_cai_a_partir_de_x_anos');
const ANOS_BAIXO = numero('nota_sobe_ate_x_anos');
if (MIN_SCORE < 0 || MIN_SCORE > 10) throw new Error('Configurações: nota_minima precisa estar entre 0 e 10 (hoje ' + MIN_SCORE + ')');
if (!(ANOS_MUITO_ALTO > ANOS_ALTO && ANOS_ALTO > ANOS_BAIXO)) {
  throw new Error('Configurações: use nota_cai_muito_a_partir_de_x_anos > nota_cai_a_partir_de_x_anos > nota_sobe_ate_x_anos (hoje ' + ANOS_MUITO_ALTO + ' / ' + ANOS_ALTO + ' / ' + ANOS_BAIXO + ')');
}
const ROLE = detector(lista(cfg.palavras_do_cargo));
const TITLE_BLOCK = detector(lista(cfg.palavras_bloqueadas_no_titulo));   // outra profissão
const STACK_BLOCK = detector(lista(cfg.palavras_bloqueadas_stack));       // stack indesejada (Júnior libera, com ressalva)
const PRIORITY = detector(lista(cfg.palavras_que_liberam_vaga));              // palavra que vence os bloqueios
const EXCLUIDA = detector(lista(cfg.senioridade_excluida)); // níveis que você não quer (estágio, sênior...); vazio = não exclui nenhum
const JUNIOR = detector(lista(cfg.palavras_do_nivel_que_busco));
const LOC_OK = detector(lista(cfg.locais_aceitos));
// "react: 1.5, node/nodejs: 1.5" vira [[detector, 1.5], ...]; "/" separa sinônimos da mesma tecnologia
const STACK = String(cfg.tecnologias ?? '').split(',').map((par) => {
  const [nomes, peso] = par.split(':');
  return [detector(String(nomes ?? '').split('/').map(limpa).filter(Boolean)), Number(peso)];
}).filter(([, peso]) => peso > 0);

// ===== helpers =====
const ENT = { '&nbsp;': ' ', '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'" };
const strip = (h) => String(h || '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')            // descrições do RSS vêm com HTML escapado
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;|&amp;|&lt;|&gt;|&quot;|&#39;/g, (m) => ENT[m])
  .replace(/\s+/g, ' ').trim();
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

// ===== normalização por fonte =====
const jobs = [];
let sourceErrors = 0;

for (const { json: j } of $input.all()) {
  if (j.error) { sourceErrors++; continue; }

  if (Array.isArray(j.jobs)) {                                   // Remotive
    for (const r of j.jobs) jobs.push({
      id: 'rm-' + r.id, source: 'Remotive', title: r.title, company: r.company_name,
      location: r.candidate_required_location, url: r.url, date: r.publication_date,
      text: strip(r.description) + ' ' + (r.tags || []).join(' '),
    });
  } else if (j.position && j.slug) {                              // RemoteOK
    jobs.push({
      id: 'rok-' + j.id, source: 'RemoteOK', title: j.position, company: j.company,
      location: j.location, url: j.url, date: j.date,
      text: strip(j.description) + ' ' + (j.tags || []).join(' '),
    });
  } else if (j.rss && j.rss.channel) {                            // We Work Remotely (XML -> JSON)
    let items = j.rss.channel.item || [];
    if (!Array.isArray(items)) items = [items];
    for (const r of items) {
      const full = String(r.title || '');
      const i = full.indexOf(':');
      jobs.push({
        id: 'wwr-' + (r.guid || r.link), source: 'WeWorkRemotely',
        title: i > 0 ? full.slice(i + 1).trim() : full, company: i > 0 ? full.slice(0, i).trim() : '',
        location: typeof r.region === 'string' ? r.region : '', url: r.link || r.guid,
        date: r.pubDate, text: strip(r.description),
      });
    }
  } else if (j.id && j.source && j.trusted) {                       // vaga de e-mail: já vem extraída pelos parsers
    jobs.push(j);
  }
  // qualquer outro formato (ex.: item vazio do gatilho) é ignorado
}

// ===== trava de sanidade =====
// Fonte que respondeu mas veio vazia é suspeita (API mudou? bloqueio?): avisa no resumo.
// Se NENHUMA fonte esperada trouxe vagas, a execução falha de propósito, e o workflow de alerta registra.
const nomesEsperados = String(cfg.fontes_esperadas ?? '').split(',').map((s) => s.trim()).filter(Boolean);
const vieram = new Set(jobs.map((j) => limpa(j.source)));
// Execução que começou por e-mail: as APIs não rodaram, só há vagas dos parsers. Aí não faz sentido cobrar as fontes esperadas.
const soEmail = $input.all().map(({ json }) => json).every((j) => !j.error && j.id && j.source && j.trusted);
const vazias = soEmail ? [] : nomesEsperados.filter((n) => !vieram.has(limpa(n)));
if (nomesEsperados.length && vazias.length === nomesEsperados.length) {
  throw new Error('Nenhuma fonte devolveu vagas (' + sourceErrors + ' com erro): confira a internet e as APIs');
}
const problemas = Math.max(sourceErrors, vazias.length); // fonte que falha também vem vazia: não conta duas vezes

// ===== score =====
function score(job) {
  const title = job.title || '';
  // 1) senioridade excluída (campo senioridade_excluida): fora. Nem Júnior nem palavra que libera a vaga salvam;
  //    para voltar a receber estágio (ou sênior), tire as palavras do campo.
  if (EXCLUIDA.test(title)) return null;
  // 2) outra profissão: fora, a não ser que o título tenha palavra que libera a vaga
  const prioridade = PRIORITY.test(title);
  if (TITLE_BLOCK.test(title) && !prioridade) return null;
  // 3) stack indesejada: fora, a não ser que tenha palavra que libera a vaga (passa normal) ou Júnior (passa com ressalva)
  const ressalvas = [];
  const stackRuim = STACK_BLOCK.acha(title);
  if (stackRuim && !prioridade) {
    if (!JUNIOR.test(title)) return null;
    // o motivo cita a palavra que bateu (lida das Configurações): nada de texto fixo sobre "Júnior"
    ressalvas.push('tem "' + stackRuim + '" (stack bloqueada), mas o título tem "' + JUNIOR.acha(title) + '" (nível que você busca)');
  }
  // 4) vaga de API precisa de palavra de cargo (e-mail e palavra que libera a vaga já contam)
  if (!job.trusted && !ROLE.test(title) && !prioridade) return null;
  // local: testa em toda vaga que traga local, exceto quando o parser do site garante que é Brasil (localConfiavel)
  if (job.location && !job.localConfiavel && !LOC_OK.test(job.location)) return null;

  const hay = title + ' ' + job.text;
  let s = job.trusted ? PESO_EMAIL : 0;
  if (ROLE.test(title) || prioridade) s += PESO_CARGO;
  let stack = 0;
  for (const [re, w] of STACK) if (re.test(hay)) stack += w;
  s += Math.min(stack, TETO_TECNOLOGIAS);
  if (JUNIOR.test(title) || prioridade) s += PESO_JUNIOR; // palavra que libera a vaga vale como Júnior: vaga de API chega sozinha à nota mínima

  const years = [...job.text.matchAll(/(\d{1,2})\s*\+?\s*(?:years?|anos)/gi)].map((m) => +m[1]);
  if (years.length) {
    const y = Math.max(...years);
    // limites vêm das Configurações (perfil); os descontos são regra de negócio (constantes lá em cima)
    if (y >= ANOS_MUITO_ALTO) s -= PENAL_ANOS_MUITO_ALTO; else if (y >= ANOS_ALTO) s -= PENAL_ANOS_ALTO; else if (y <= ANOS_BAIXO) s += BONUS_ANOS_BAIXO;
  }
  if (LOC_RESTRICT.test(job.text)) s -= PENAL_EUA_EUROPA;
  return { nota: Math.max(0, Math.min(10, Math.round(s))), ressalvas };
}

// ===== dedup (memória entre execuções) =====
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
for (const k of Object.keys(store.seen)) {
  if (now - store.seen[k] > SEEN_TTL_DAYS * 864e5) delete store.seen[k];
}

const fresh = [];
for (const job of jobs) {
  if (job.date) {
    const t = Date.parse(job.date);
    if (!isNaN(t) && now - t > MAX_AGE_DAYS * 864e5) continue;
  }
  const k1 = norm(job.id);
  const k2 = norm(job.company) + '|' + norm(job.title);
  if (store.seen[k1] || (job.company && store.seen[k2])) continue;
  const r = score(job);
  if (r === null || r.nota < MIN_SCORE) continue;
  store.seen[k1] = now;
  if (job.company) store.seen[k2] = now;
  fresh.push({ ...job, score: r.nota, ressalvas: r.ressalvas });
}
// normais primeiro, "com ressalvas" depois; dentro de cada grupo, maior nota primeiro
fresh.sort((a, b) => (a.ressalvas.length > 0) - (b.ressalvas.length > 0) || b.score - a.score);

// ===== mensagens =====
const day = new Date().toLocaleDateString('pt-BR', { timeZone: FUSO });
const detalhes = [];
if (vazias.length) detalhes.push(`sem vagas: ${vazias.join(', ')}`);
if (sourceErrors) detalhes.push(`${sourceErrors} com erro`);
const warn = detalhes.length ? `\n⚠️ ${detalhes.join(' · ')}.` : '';

if (!fresh.length) {
  // manda aviso mesmo sem vaga: prova de que a automação rodou
  const hora = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: FUSO });
  return [{ json: { text: TEXTO_CALMO(day, hora, jobs.length, warn),
    vagas: [], analisadas: jobs.length, fontesComErro: problemas } }];
}

const fmt = (j) => `⭐ ${j.score}/10 · ${j.title}${j.company ? ' — ' + j.company : ''}\n📍 ${j.location || 'n/d'} · ${j.source}${j.ressalvas.length ? '\n⚠️ ' + j.ressalvas.join(' · ') : ''}\n${j.url}`;
const primeiraRessalva = fresh.find((j) => j.ressalvas.length);
// junta as vagas em mensagens; começa outra mensagem quando passaria do limite do embed
const cabecalho = TEXTO_NOVAS(fresh.length, warn);
const blocos = [];
let atual = cabecalho;
for (const j of fresh) {
  const titulo = j === primeiraRessalva ? '⚠️ COM RESSALVAS: passaram por terem no título uma palavra do nível que você busca (' + String(cfg.palavras_do_nivel_que_busco).split(',').map((s) => s.trim()).filter(Boolean).join(', ') + '), mas têm algo que você bloqueou. Para mudar, veja os filtros no nó Configurações.\n\n' : '';
  const bloco = titulo + fmt(j);
  if ((atual + '\n\n' + bloco).length > MAX_CHARS) { blocos.push(atual); atual = bloco; }
  else atual += '\n\n' + bloco;
}
blocos.push(atual);
return blocos.map((text) => ({ json: { text: text.slice(0, 4000), vagas: fresh, analisadas: jobs.length, fontesComErro: problemas } }));

// Monta a página inicial: histórico das últimas vagas, 10 por página.
// Todos os itens de entrada carregam a mesma lista de vagas da execução; basta o primeiro.
const FUSO = $env.GENERIC_TIMEZONE || 'America/Sao_Paulo'; // fuso das datas e horas: vem do .env (GENERIC_TIMEZONE); sem ele, Brasília
const N8N_URL = 'http://localhost:5678'; // endereço do seu n8n (o link "Buscar agora" abre o webhook dele)
const HISTORICO_MAX = 200;        // quantas vagas a página lembra
// Tema (identidade): vem do .env (TEMA). "aranha" (padrão) ou "neutro". Também decide o prefixo dos nomes de arquivo.
const NEUTRO = $env.TEMA === 'neutro';
const NOME = NEUTRO ? 'Radar de Vagas' : 'Meu Sentido de Aranha';
const PREFIXO = NEUTRO ? '' : 'spider-man-';   // spider-man-alertas.html (aranha) ou alertas.html (neutro)
const TEXTO_SEM_VAGAS = NEUTRO ? 'Nenhuma vaga por enquanto.' : 'Sentido de aranha calmo: nenhuma vaga por enquanto.';
const j = $input.first().json;
// palavras do nível buscado vindas das Configurações (para explicar a ressalva sem texto fixo)
const palavrasJunior = String($('Configurações').first().json.palavras_do_nivel_que_busco || '').split(',').map((s) => s.trim()).filter(Boolean).join(', ');

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
// o link vem de fonte externa: só aceita http(s), para não virar "javascript:..."
const linkSeguro = (u) => (/^https?:\/\//i.test(String(u)) ? esc(u) : '#');
const formata = (iso) => new Date(iso).toLocaleString('pt-BR', { timeZone: FUSO });

const d = new Date();
// o formato sueco já vem como "2026-11-06 20:41:55"; ficamos com ano até minutos
const agora = d.toLocaleString('sv-SE', { timeZone: FUSO }).slice(0, 16); // "2026-11-06 20:41"
const stamp = agora.replace(' ', '_').replace(':', '');                    // "2026-11-06_2041"
const quando = formata(d.toISOString());

// --- histórico: fica na memória do workflow (só é gravada nas execuções automáticas) ---
const store = $getWorkflowStaticData('global');
const novas = (j.vagas || []).map((v) => ({
  score: v.score, title: v.title, company: v.company, location: v.location,
  source: v.source, url: v.url, encontradaEm: d.toISOString(), ressalvas: v.ressalvas || [],
}));
const urlsNovas = new Set(novas.map((v) => v.url));
const antigas = (store.historico || []).filter((v) => !urlsNovas.has(v.url));
store.historico = [...novas, ...antigas].slice(0, HISTORICO_MAX);
const lista = store.historico;

const analisadas = j.analisadas ?? 0;
const erros = j.fontesComErro || 0;

// nota 8 ou mais ganha destaque vermelho; as demais ficam em azul
const classeNota = (n) => (n >= 8 ? 'alta' : 'media');

const cartoes = lista.map((v) => `
      <li class="cartao" data-ressalva="${(v.ressalvas || []).length ? 'sim' : 'nao'}">
        <div class="nota ${classeNota(v.score)}" aria-label="Nota ${esc(v.score)} de 10"><span>${esc(v.score)}</span><small>/10</small></div>
        <div class="corpo">
          <h2>${esc(v.title)}${urlsNovas.has(v.url) ? ' <span class="etiqueta">Nova</span>' : ''}</h2>
          <p class="empresa">${esc(v.company || 'Empresa não informada')}</p>
          <p class="meta">${esc(v.location || 'Local não informado')} &middot; ${esc(v.source)} &middot; encontrada em ${esc(formata(v.encontradaEm))}</p>
          ${(v.ressalvas || []).length ? `<p class="ressalva">⚠️ Ressalva: ${esc(v.ressalvas.join(' · '))}</p>` : ''}
        </div>
        <a class="botao" href="${linkSeguro(v.url)}" target="_blank" rel="noopener noreferrer">Abrir vaga</a>
      </li>`).join('');

const comRessalva = lista.filter((v) => (v.ressalvas || []).length).length;
const filtros = `<nav class="filtros" id="filtros" aria-label="Filtrar vagas">
