const script = `
(function () {
  var POR_PAGINA = 10;
  var todos = Array.prototype.slice.call(document.querySelectorAll('.lista > li'));
  var nav = document.getElementById('paginas');
  var filtros = document.getElementById('filtros');
  var semResultado = document.getElementById('sem-resultado');
  // ao voltar da página "Buscando vagas" (botão Voltar), o navegador pode mostrar a cópia antiga: recarrega para ver as novas
  window.addEventListener('pageshow', function (e) { if (e.persisted) location.reload(); });
  if (!nav) return;
  // o endereço guarda o filtro e a página: #com-p2 = "com ressalvas", página 2 (vazio = todas, página 1)
  function estado() {
    var m = /^#(?:(com|sem)-?)?(?:p([0-9]+))?$/.exec(location.hash);
    return { f: (m && m[1]) || 'todas', p: m && m[2] ? parseInt(m[2], 10) : 1 };
  }
  function mostrar() {
    var e = estado();
    var visiveis = todos.filter(function (li) {
      var tem = li.getAttribute('data-ressalva') === 'sim';
      return e.f === 'todas' || (e.f === 'com') === tem;
    });
    var total = Math.max(1, Math.ceil(visiveis.length / POR_PAGINA));
    var p = Math.min(Math.max(e.p, 1), total);
    todos.forEach(function (li) { li.hidden = true; });
    visiveis.forEach(function (li, i) { li.hidden = Math.floor(i / POR_PAGINA) + 1 !== p; });
    if (semResultado) semResultado.hidden = visiveis.length > 0;
    var dica = document.getElementById('dica-ressalva');
    if (dica) dica.hidden = e.f !== 'com'; // a explicação só aparece na visão "Com ressalvas"
    var prefixo = e.f === 'todas' ? '' : e.f + '-';
    nav.innerHTML = '';
    for (var n = 1; total > 1 && n <= total; n++) {
      var a = document.createElement('a');
      a.href = '#' + prefixo + 'p' + n;
      a.textContent = n;
      if (n === p) a.setAttribute('aria-current', 'page');
      nav.appendChild(a);
    }
    if (filtros) {
      Array.prototype.forEach.call(filtros.querySelectorAll('a'), function (a) {
        if (a.getAttribute('data-f') === e.f) a.setAttribute('aria-current', 'true');
        else a.removeAttribute('aria-current');
      });
    }
  }
  window.addEventListener('hashchange', mostrar);
  mostrar();
})();`;

