// Parser dos e-mails do Glassdoor, dentro do próprio nó (só regex, sem biblioteca). Para ajustar o formato de um e-mail, edite aqui.
// Parser do alerta de vagas do Glassdoor (e-mail HTML -> lista de vagas).
// Sem DOM e sem biblioteca: só regex, porque o nó Code do n8n não tem cheerio por padrão.
// Cada vaga é UM link <a href="...jobListing.htm?...jobListingId=123..."> ... </a>.
// Dentro do link, os textos aparecem sempre nesta ordem:
//   empresa, [nota "4.2 ★"], título, local, [salário], [selo "Candidatura rápida"], idade ("2 dia(s)" / "Recém-publicado")

const decodifica = (s) => s
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&nbsp;/g, ' ');

function parseGlassdoor(html, agora = new Date()) {
  html = String(html).replace(/<!--[\s\S]*?-->/g, ''); // comentários HTML podem conter <a> de exemplo
  const vagas = [];
  const vistos = new Set();
  // só links de vaga; "Ver mais vagas" e "Criar" (alertas relacionados) têm outro formato e ficam de fora
  const reLink = /<a\b[^>]*href="([^"]*jobListing\.htm[^"]*)"[^>]*>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = reLink.exec(html))) {
    const href = decodifica(m[1]);
    const id = (href.match(/[?&]jobListingId=(\d+)/) || [])[1];
    if (!id || vistos.has(id)) continue;
    vistos.add(id);

    // troca cada tag por quebra de linha e fica só com os textos não vazios
    const partes = m[2].replace(/<[^>]+>/g, '\n').split('\n')
      .map((s) => decodifica(s).replace(/\s+/g, ' ').trim()).filter(Boolean);

    let i = 0;
    const empresa = partes[i++];
    let notaEmpresa = null;
    if (/^\d([.,]\d)?\s*★$/.test(partes[i] || '')) notaEmpresa = parseFloat(partes[i++].replace(',', '.'));
    const titulo = partes[i++];
    const local = partes[i++];
    const resto = partes.slice(i);
    const idadeTxt = resto.find((p) => /dia\(s\)|Recém/i.test(p)) || '';
    const salario = resto.find((p) => /R\$/.test(p)) || null;
    const dias = /Recém/i.test(idadeTxt) ? 0 : parseInt((idadeTxt.match(/(\d+)\s*dia/) || [])[1] ?? '', 10);

    vagas.push({
      id: 'glassdoor:' + id,
      source: 'Glassdoor',
      title: titulo,
      company: empresa,
      location: local,
      // link limpo: o original leva o ID criptografado do usuário (uido) e outros rastreadores
      url: 'https://www.glassdoor.com.br/job-listing/j?jl=' + id,
      date: Number.isNaN(dias) ? null : new Date(agora.getTime() - dias * 86400000).toISOString(),
      text: '',       // o e-mail não traz descrição: a nota sai só do título
      trusted: true,  // mesmo formato que o filtro espera das vagas de e-mail
      localConfiavel: true, // busca feita no glassdoor.com.br: o local (ex.: "Trabalho remoto") já é Brasil, o filtro não precisa testar
      notaEmpresa,
      salario,
    });
  }
  return vagas;
}

