  const vagas = parseGlassdoor(html, new Date(email.date || Date.now()));

  // Conferência: links de vaga no e-mail x vagas que o parser extraiu. Diferente = o formato mudou: falha de propósito
  // (o workflow de alerta registra), em vez de perder vagas em silêncio.
  const ids = new Set();
  for (const m of html.replace(/<!--[\s\S]*?-->/g, '').matchAll(/href="([^"]*jobListing\.htm[^"]*)"/gi)) {
    const id = decodifica(m[1]).match(/[?&]jobListingId=(\d+)/);
    if (id) ids.add(id[1]);
  }
