// Parser dos e-mails do LinkedIn, dentro do próprio nó (só regex, sem biblioteca). Para ajustar o formato de um e-mail, edite aqui.
// Parser do alerta de vagas do LinkedIn (e-mail HTML -> lista de vagas).
// Sem DOM e sem biblioteca: só regex, porque o nó Code do n8n não tem cheerio por padrão.
// Estrutura de cada vaga no e-mail "email_job_alert_digest_01":
//   <a href=".../jobs/view/ID/?trackingId=...&trk=...company_logo...">  (só o logo, sem texto)
//   <a href=".../jobs/view/ID/?...&trk=...job_posting...">             (envolve o cartão inteiro)
//      <a href=".../jobs/view/ID/?...&trk=...jobcard_body...">TÍTULO</a>   (link aninhado: HTML inválido, mas é assim que vem)
//      <p>EMPRESA &middot; LOCAL</p>
//      <p class="job-card-flavor__detail">1 connection</p> <p class="job-card-flavor__detail">Easy Apply</p>
// O e-mail NÃO traz a data da vaga: usamos a data do e-mail (o alerta só lista vagas novas).

const decodifica = (s) => s
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/&middot;/g, '·')
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)));

const texto = (s) => decodifica(s.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();

// ids únicos de vaga que aparecem no e-mail (também serve de conferência: quantas vagas deveriam sair)
function idsNoEmail(html) {
  html = String(html).replace(/<!--[\s\S]*?-->/g, '');
  const ids = [];
  for (const m of html.matchAll(/href="[^"]*linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/gi)) {
    if (!ids.includes(m[1])) ids.push(m[1]);
  }
  return ids;
}

function parseLinkedin(html, dataEmail = new Date()) {
  html = String(html).replace(/<!--[\s\S]*?-->/g, ''); // comentários podem conter <a> de exemplo
  const vagas = [];
  for (const id of idsNoEmail(html)) {
    // 1) caminho normal: o link "jobcard_body" é o do título
    let titulo = '';
    let depois = 0;
    const abre = new RegExp('<a\\b[^>]*href="[^"]*jobs/view/' + id + '[^"]*jobcard_body[^"]*"[^>]*>', 'i').exec(html);
    if (abre) {
      const ini = abre.index + abre[0].length;
      const fim = html.indexOf('</a>', ini);
      if (fim > -1) { titulo = texto(html.slice(ini, fim)); depois = fim; }
    }
    // 2) plano B: primeiro link dessa vaga que tenha texto
    if (!titulo) {
      const reA = new RegExp('<a\\b[^>]*href="[^"]*jobs/view/' + id + '[^"]*"[^>]*>([\\s\\S]*?)</a>', 'gi');
      let m;
      while ((m = reA.exec(html))) {
        const t = texto(m[1]);
        if (t) { titulo = t; depois = m.index + m[0].length; break; }
      }
    }
    if (!titulo) continue; // vaga sem título legível: a conferência (ids x vagas) acusa

    // trecho do cartão: da pós-título até o próximo link de vaga (máx. 3000 caracteres)
    const prox = html.indexOf('jobs/view/', depois);
    const fatia = html.slice(depois, prox > -1 ? Math.min(prox, depois + 3000) : depois + 3000);

    // primeira linha <p>: "EMPRESA · LOCAL"
    const p1 = /<p\b[^>]*>([\s\S]*?)<\/p>/i.exec(fatia);
    const linha = p1 ? texto(p1[1]) : '';
    const corte = linha.indexOf(' · ');
    const empresa = corte > -1 ? linha.slice(0, corte).trim() : linha;
    const local = corte > -1 ? linha.slice(corte + 3).trim() : '';

    // salário (só algumas vagas têm): é um segundo <p> logo depois do "EMPRESA · LOCAL", sem a classe dos selos
    const outrosP = [...fatia.matchAll(/<p\b([^>]*)>([\s\S]*?)<\/p>/gi)].slice(1)
      .filter((m) => !/job-card-flavor__detail/.test(m[1])).map((m) => texto(m[2])).filter(Boolean);
    const salario = outrosP.find((t) => /[€$£]|R\$|\/\s*(year|yr|month|ano|mês)/i.test(t)) || null;

    // selos do cartão ("1 connection", "Easy Apply", "Actively recruiting"...)
    const selos = [...fatia.matchAll(/<p\b[^>]*job-card-flavor__detail[^>]*>([\s\S]*?)<\/p>/gi)].map((m) => texto(m[1])).filter(Boolean);

    vagas.push({
      id: 'linkedin:' + id,
      source: 'LinkedIn',
      title: titulo,
      company: empresa,
      location: local,
      // link limpo: o original leva trackingId, refId, otpToken (rastreio ligado ao usuário)
      url: 'https://www.linkedin.com/jobs/view/' + id,
      date: dataEmail.toISOString(),
      text: '',       // o e-mail não traz descrição: a nota sai só do título
      trusted: true,  // mesmo formato que o filtro espera das vagas de e-mail
      salario,
      selos,
    });
  }
  return vagas;
}

