  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)));
const texto = (s) => decodifica(s.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '');

const limpaHtml = (html) => String(html).replace(/<!--[\s\S]*?-->/g, '').replace(/<style[\s\S]*?<\/style>/gi, '');

// Todo cartão de vaga: <h2><a href="link do Indeed">título</a></h2>. Outros <h2> (ex.: "7 vagas abertas de...") não têm link.
function cartoes(html) {
  html = limpaHtml(html);
  const lista = [];
  const re = /<h2\b[^>]*>\s*<a\b[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>\s*<\/h2>/gi;
  let m;
  while ((m = re.exec(html))) {
    const href = decodifica(m[1]);
    if (!/(^|\/\/)(?:[a-z]+\.)?indeed\.com\//i.test(href)) continue;
    lista.push({ href, titulo: texto(m[2]), fim: m.index + m[0].length });
  }
  return lista;
}

// quantas vagas o próprio e-mail diz ter: "7 vagas abertas de Desenvolvedor Node Js Júnior" (null se não disser)
function anunciadas(html) {
  const m = limpaHtml(html).match(/<h2\b[^>]*>\s*(\d+)\s+vagas?\b/i);
  return m ? Number(m[1]) : null;
}

// Conferência para o n8n: cartões no e-mail x vagas extraídas. Diferente = o formato mudou (falhar de propósito).
function conferencia(html, vagas) {
  return { cartoes: cartoes(html).length, anunciadas: anunciadas(html), extraidas: vagas.length };
}

// jk = identificador público da vaga no Indeed (16 caracteres hex)
function jkDoLink(href, { zlib } = {}) {
  let m = href.match(/[?&]jk=([0-9a-f]{16})/i);
  if (m) return m[1];
  m = href.match(/cts\.indeed\.com\/v3\/([A-Za-z0-9_-]+)\//i);
  if (m && zlib) {
    try {   // o pedaço do meio é um JSON comprimido: {"u":"https://br.indeed.com/rc/clk?jk=ID&...", ...}
      const b64 = m[1].replace(/-/g, '+').replace(/_/g, '/');
      const json = zlib.gunzipSync(Buffer.from(b64, 'base64')).toString('utf8');
      const j = json.match(/jk=([0-9a-f]{16})/i);
      if (j) return j[1];
    } catch (e) { /* sem jk: usa o plano B */ }
  }
  return null;
}

const ehSalario = (t) => /R\$|\bpor (mês|mes|hora|ano|dia|semana)\b/i.test(t);
const ehIdade = (t) => /^(há\s+\d|recém|publicad|ativ[ao] há|hoje|ontem)/i.test(t);
const ehExtra = (t) => /^candidate-se/i.test(t);

function diasDaIdade(t) {
  if (!t) return null;
  if (/recém|hoje|hora/i.test(t)) return 0;
  if (/ontem/i.test(t)) return 1;
  const n = t.match(/(\d+)\+?\s*dia/i);
  return n ? Number(n[1]) : null;
}

// opts.zlib: passar require('zlib') para o jk do e-mail "match" (no n8n: NODE_FUNCTION_ALLOW_BUILTIN=zlib)
function parseIndeed(html, dataEmail = new Date(), opts = {}) {
  html = limpaHtml(html);
  const cards = cartoes(html);
  const h2s = [...html.matchAll(/<h2\b/gi)].map((m) => m.index);
  const vagas = [];
  const vistos = new Set();
  for (const c of cards) {
    if (!c.titulo) continue; // sem título legível: a conferência (cartões x extraídas) acusa
    // trecho deste cartão: até o próximo <h2> (qualquer um), no máximo 20000 caracteres (os estilos inline do e-mail real são enormes)
    const prox = h2s.find((i) => i >= c.fim);
    const fatia = html.slice(c.fim, Math.min(prox ?? Infinity, c.fim + 20000));

    const ps = [...fatia.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)].map((m) => texto(m[1])).filter(Boolean);
    const empresa = ps[0] || '';
    const proximo = ps[1] || '';
    const local = proximo && !ehSalario(proximo) && !ehIdade(proximo) && !ehExtra(proximo) ? proximo : '';
    const topo = ps.slice(0, 6);
    const salario = topo.find(ehSalario) || null;
    const idade = topo.find(ehIdade) || '';
    const facil = topo.some(ehExtra);

    // blocos <h3>Título</h3> ... (só o e-mail "match" tem)
    const secoes = {};
    for (const m of fatia.matchAll(/<h3\b[^>]*>([\s\S]*?)<\/h3>([\s\S]*?)(?=<h3\b|$)/gi)) secoes[texto(m[1])] = m[2];
    const tipo = secoes['Tipo de vaga'] ? texto(secoes['Tipo de vaga']) : null;
    const ambiente = secoes['Ambiente de trabalho'] ? texto(secoes['Ambiente de trabalho']) : null;
    const beneficios = secoes['Benefício'] ? [...secoes['Benefício'].matchAll(/<li\b[^>]*>([\s\S]*?)<\/li>/gi)].map((m) => texto(m[1])) : [];
    const descricao = (secoes['Pré-visualização da descrição da vaga'] ? texto(secoes['Pré-visualização da descrição da vaga']) : '')
      .replace(/\s*Saiba mais\s*$/i, '');

    const jk = jkDoLink(c.href, opts);
    const id = jk ? 'indeed:' + jk : 'indeed:' + norm(empresa) + '|' + norm(c.titulo);
    if (vistos.has(id)) continue;
    vistos.add(id);

    const dias = diasDaIdade(idade);
    vagas.push({
      id,
      source: 'Indeed',
      title: c.titulo,
      company: empresa,
      location: local,
      // link limpo: os do e-mail levam tokens ligados ao usuário (qd, rd, tk, bb... ou o gzip do cts)
      url: jk ? 'https://br.indeed.com/viewjob?jk=' + jk
              : 'https://br.indeed.com/jobs?q=' + encodeURIComponent(c.titulo + ' ' + empresa),
      date: new Date(dataEmail.getTime() - (dias ?? 0) * 86400000).toISOString(),
      text: descricao,  // só o e-mail "match" traz um trecho da descrição; no resumo fica vazio
      trusted: true,    // mesmo formato que o filtro espera das vagas de e-mail
      // sem localConfiavel: o alerta do Indeed traz vagas de qualquer cidade (ex.: Ribeirão Preto), o filtro precisa olhar o local
      salario, tipo, ambiente, beneficios, candidaturaFacil: facil,
    });
  }
  return vagas;
}

// ===== Entrada do nó =====
// Chega 1 item por e-mail (do gatilho IMAP). Este nó só trata e-mails do Indeed (resumo do alerta e "match"); os outros passam batido.
// O e-mail "match" esconde o id da vaga dentro de um link comprimido: precisa do módulo zlib liberado
// (NODE_FUNCTION_ALLOW_BUILTIN=zlib no docker-compose.yml). Sem ele, as vagas saem do mesmo jeito, só com id por empresa+título.
let zlib = null;
try { zlib = require('zlib'); } catch (e) { /* zlib não liberado: segue sem */ }

const remetente = (j) => String(j.from?.text ?? j.from ?? '').toLowerCase();
const saida = [];
for (const { json: email } of $input.all()) {
  if (!remetente(email).includes('indeed')) continue;
  const html = String(email.html || email.textAsHtml || '');
  const vagas = parseIndeed(html, new Date(email.date || Date.now()), { zlib });

  // Conferência: cartões de vaga no e-mail x vagas extraídas. Diferente = o formato mudou: falha de propósito.
  const c = conferencia(html, vagas);
  if (c.cartoes !== c.extraidas) {
    throw new Error(`Indeed: o e-mail tem ${c.cartoes} vaga(s) e o parser extraiu ${c.extraidas}. O formato do e-mail mudou?`);
  }
  saida.push(...vagas.map((json) => ({ json })));
}
return saida;

// Página que o navegador mostra quando você abre o link "Buscar agora" (webhook "Rodar tudo").
// O nó seguinte responde com ela NA HORA; a busca continua rodando por trás e o resultado
// vai para o Discord e para a página de vagas. Mesmas cores e fontes da página de vagas.
const NEUTRO = $env.TEMA === 'neutro';   // tema do .env (mesmo critério da página de vagas)
const NOME = NEUTRO ? 'Radar de Vagas' : 'Meu Sentido de Aranha';

const html = `<!doctype html>
<html lang="pt-BR">
<head>
