  h1 { margin: 0; font-family: "Arial Black", "Segoe UI Black", system-ui, sans-serif; font-size: clamp(1.6rem, 5vw, 2.4rem); text-transform: uppercase; letter-spacing: .02em; line-height: 1.1; }
  .sub { margin: .4rem 0 0; color: var(--suave); }
  .aviso { background: var(--card); border: 1px solid var(--borda); border-top: 4px solid var(--azul); border-radius: 8px; padding: 1.25rem 1.5rem; }
  .aviso h2 { margin: 0 0 .5rem; font-size: 1.2rem; }
  .aviso p { margin: 0 0 1rem; }
  .suave { color: var(--suave); font-size: .9rem; }
  .botao { display: inline-block; padding: .55rem 1rem; border: 2px solid var(--azul); border-radius: 6px; color: var(--azul); font-weight: 700; text-decoration: none; }
